public with sharing class OrderPayloadParser {

    // ----- Inner Classes -----

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    // ----- Parse -----

    public static OrderPayloadParser.Order parse(String body) {
        // 1. Validate body is not null/blank
        if (body == null || body.trim().length() == 0) {
            throw new PayloadException();
        }

        // 2. Parse JSON
        Object payloadObj;
        try {
            payloadObj = JSON.parse(body);
        } catch (System.Exception e) {
            throw new PayloadException();
        }

        // 3. Must be a JSON object (Map)
        if (payloadObj == null || !(payloadObj instanceof Map)) {
            throw new PayloadException();
        }
        Map<String, Object> payload = (Map<String, Object>) payloadObj;

        // 4. Validate 'number' – must exist, be a non‑blank String
        if (!payload.containsKey('number')) {
            throw new PayloadException();
        }
        Object numObj = payload.get('number');
        if (numObj == null || !(numObj instanceof String)) {
            throw new PayloadException();
        }
        String orderNumber = (String) numObj;
        if (orderNumber.trim().length() == 0) {
            throw new PayloadException();
        }

        // 5. Optional 'date' – ISO yyyy‑MM‑dd
        Date orderDate = null;
        if (payload.containsKey('date')) {
            Object dateObj = payload.get('date');
            if (dateObj != null && dateObj instanceof String) {
                try {
                    orderDate = Date.valueOf((String) dateObj);
                } catch (System.Exception e) {
                    // keep null if format is wrong
                }
            }
        }

        // 6. Optional 'currency'
        String currencyCode = null;
        if (payload.containsKey('currency')) {
            Object curObj = payload.get('currency');
            if (curObj != null && curObj instanceof String) {
                currencyCode = (String) curObj;
            }
        }

        // 7. Optional 'customer' → email
        String customerEmail = null;
        if (payload.containsKey('customer') && payload.get('customer') instanceof Map) {
            Map<String, Object> customer = (Map<String, Object>) payload.get('customer');
            if (customer.containsKey('email') && customer.get('email') != null && customer.get('email') instanceof String) {
                customerEmail = (String) customer.get('email');
            }
        }

        // 8. Prepare lines container
        List<Map<String, Object>> linesRaw = new List<Map<String, Object>>();
        if (payload.containsKey('lines') && payload.get('lines') != null) {
            Object linesObj = payload.get('lines');
            if (linesObj instanceof List) {
                linesRaw = (List<Map<String, Object>>) linesObj;
            }
        }

        List<Line> lines = new List<Line>();
        Decimal total = 0;

        for (Map<String, Object> lineObj : linesRaw) {
            // ---- sku ----
            if (!lineObj.containsKey('sku') || lineObj.get('sku') == null) {
                throw new PayloadException();
            }
            Object skuObj = lineObj.get('sku');
            if (!(skuObj instanceof String)) {
                throw new PayloadException();
            }
            String sku = (String) skuObj;
            if (sku.trim().length() == 0) {
                throw new PayloadException();
            }

            // ---- quantity ----
            if (!lineObj.containsKey('quantity')) {
                throw new PayloadException();
            }
            Object qtyObj = lineObj.get('quantity');
            if (qtyObj == null) {
                throw new PayloadException();
            }
            Integer quantity;
            if (qtyObj instanceof Integer) {
                quantity = (Integer) qtyObj;
            } else if (qtyObj instanceof Decimal) {
                quantity = Integer.valueOf((Decimal) qtyObj);
            } else {
                try {
                    quantity = Integer.valueOf(String.valueOf(qtyObj));
                } catch (Exception) {
                    throw new PayloadException();
                }
            }
            if (quantity <= 0) {
                throw new PayloadException();
            }

            // ---- unitPrice ----
            if (!lineObj.containsKey('unitPrice')) {
                throw new PayloadException();
            }
            Object priceObj = lineObj.get('unitPrice');
            if (priceObj == null) {
                throw new PayloadException();
            }
            Decimal unitPrice;
            if (priceObj instanceof Decimal) {
                unitPrice = (Decimal) priceObj;
            } else if (priceObj instanceof Integer) {
                unitPrice = Decimal.valueOf((Integer) priceObj);
            } else {
                try {
                    unitPrice = Decimal.valueOf(String.valueOf(priceObj));
                } catch (Exception) {
                    throw new PayloadException();
                }
            }
            if (unitPrice < 0) {
                throw new PayloadException();
            }

            // ---- discount ----
            Decimal discount = 0;
            if (lineObj.containsKey('discount') && lineObj.get('discount') != null) {
                Object discObj = lineObj.get('discount');
                if (discObj instanceof Decimal) {
                    discount = (Decimal) discObj;
                } else if (discObj instanceof Integer) {
                    discount = Decimal.valueOf((Integer) discObj);
                } else {
                    try {
                        discount = Decimal.valueOf(String.valueOf(discObj));
                    } catch (Exception) {
                        // keep 0 if unparseable
                    }
                }
            }

            // ---- lineTotal = quantity * unitPrice * (1 - discount), rounded to 2 decimals ----
            Decimal lineTotal = quantity * unitPrice * (1 - discount);
            lineTotal = lineTotal.setScale(2, System.RoundingMode.HALF_UP);

            Line line = new Line();
            line.sku = sku;
            line.quantity = quantity;
            line.unitPrice = unitPrice;
            line.discount = discount;
            line.lineTotal = lineTotal;
            lines.add(line);

            total += lineTotal;
        }

        // 9. Assemble Order
        Order order = new Order();
        order.orderNumber = orderNumber;
        order.orderDate = orderDate;
        order.currencyCode = currencyCode;
        order.customerEmail = customerEmail;
        order.lines = lines;
        order.total = total; // 0 when there are no lines
        return order;
    }

    // ----- toAcknowledgement -----

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines.size());
        ack.put('total', order.total);
        return JSON.generate(ack);
    }
}
