public with sharing class LogPurgeJob implements Schedulable {
    public LogPurgeJob() {
        // no-argument constructor
    }

    public void execute(SchedulableContext sc) {
        Date thirtyDaysAgo = Date.today().addDays(-30);
        Date hundredEightyDaysAgo = Date.today().addDays(-180);

        List<FB_Integration_Log__c> logsToDelete = new List<FB_Integration_Log__c>();
        for (FB_Integration_Log__c log : [
            SELECT Id, Level__c, CreatedDate
            FROM FB_Integration_Log__c
            WHERE ((Level__c != 'ERROR' AND CreatedDate < :thirtyDaysAgo)
               OR (Level__c = 'ERROR' AND CreatedDate < :hundredEightyDaysAgo))
        ]) {
            logsToDelete.add(log);
            if (logsToDelete.size() >= 2000) {
                delete logsToDelete;
                logsToDelete = new List<FB_Integration_Log__c>();
            }
        }
        if (!logsToDelete.isEmpty()) {
            delete logsToDelete;
        }
    }

    public static Id scheduleNightly() {
        String jobName = 'Log purge (nightly)';
        String cronExpr = '0 2 * * *';

        // Cancel any existing scheduled job with the same name so System.schedule can re-run
        for (AsyncApexJob job : [
            SELECT Id
            FROM AsyncApexJob
            WHERE Name = :jobName
            AND ApexClass.Name = 'LogPurgeJob'
            AND Status = 'Scheduled'
        ]) {
            System.abortJob(job.Id);
        }

        Id jobId = System.schedule(jobName, cronExpr, new LogPurgeJob());
        return jobId;
    }
}
