     *
     * @param accountIds The set of account IDs to calculate rollups for.
     * @return A map where each key is a requested account ID and the value is the total won amount
     *         for the current calendar year. Accounts with no qualifying opportunities map to 0.
     *         If accountIds is null or empty, an empty map is returned.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        // Single aggregate SOQL query: sum Amount for won opportunities in the current year, grouped by AccountId
        Map<Id, Decimal> wonByAccount = new Map<Id, Decimal>();
        for (AggregateResult ar : [
            SELECT AccountId accountId, COALESCE(SUM(Amount), 0) total
            FROM Opportunity
            WHERE IsWon = true
              AND AccountId IN :accountIds
              AND YEAR(CloseDate) = YEAR(TODAY())
            GROUP BY AccountId
        ]) {
            Id aId = (Id) ar.get('accountId');
            Decimal t = (Decimal) ar.get('total');
            wonByAccount.put(aId, t);
        }

        // Ensure every requested account Id is a key, defaulting to 0 when no qualifying opportunities exist
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id acctId : accountIds) {
            result.put(acctId, wonByAccount.get(acctId) != null ? wonByAccount.get(acctId) : 0);
        }
        return result;
    }
}
