            Account.Name,
            Account.Industry
        };

        // Dynamically include fields from the Credit_Review field set.
        // Admins can add fields to this field set without code changes;
        // we use Schema.FieldSetUtil to avoid hard-coding AnnualRevenue or Rating.
        for (String fieldName : Schema.FieldSetUtil.getFieldSetItems(Account.SObjectType, 'Credit_Review')) {
            Schema.SObjectField field = Account.SObjectType.getDescribe().fields.getMap().get(fieldName);
            if (field != null) {
                fieldList.add(field);
            }
        }

        return fieldList;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        // Build the contact subquery SELECT list from the existing ContactsSelector
        // so it uses that selector's fields (Id, FirstName, LastName, Email, AccountId).
        ContactsSelector cs = new ContactsSelector();
        List<Schema.SObjectField> contactFields = cs.getSObjectFieldList();
        List<String> contactFieldNames = new List<String>();
        for (Schema.SObjectField f : contactFields) {
            contactFieldNames.add(f.getDescribe().getName());
        }
        String subqueryFields = String.join(contactFieldNames, ', ');

        // Build the main SELECT list from the selector's field list
        List<Schema.SObjectField> mainFields = getSObjectFieldList();
        List<String> mainFieldNames = new List<String>();
        for (Schema.SObjectField f : mainFields) {
            mainFieldNames.add(f.getDescribe().getName());
        }
        String mainFieldsStr = String.join(mainFieldNames, ', ');

        // Construct the SOQL query with a Contacts child subquery and USER_MODE
        String query = 'SELECT ' + mainFieldsStr + ' FROM Account WHERE Id IN :accountIds '
                     + '(SELECT ' + subqueryFields + ' FROM Contacts) WITH USER_MODE';

        return (List<Account>) Database.query(query);
    }
}
