/**
 * Service class for onboarding Accounts and their related Contacts using the fflib SObject Unit of Work pattern.
 * All records are created and committed through a single fflib_SObjectUnitOfWork instance.
 */
public class AccountOnboardingService {

    /**
     * Creates Accounts and associated Contacts from a map of account names to lists of contact last names.
     *
     * @param contactLastNamesByAccountName A map where the key is the Account Name and the value is a list of Contact LastNames.
     * @return A list of newly created Accounts with Ids populated. Returns an empty list if the input map is null or empty.
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        // Return empty list early if map is null or empty – no records written.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // Single Unit of Work instance – all records are written through this, committed once.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork();
        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            // Create the Account named after the map key.
            Account a = new Account(Name = accountName);
            uow.add(a);
            newAccounts.add(a);

            // For every last name in the entry's list, create a Contact linked to this Account.
            for (String lastName : contactLastNamesByAccountName.get(accountName)) {
                Contact c = new Contact(LastName = lastName, AccountId = a.Id);
                uow.add(c);
            }
        }

        // Commit all accumulated records in a single DML operation.
        // commitWork() returns void in this context; Ids are populated on the SObject references after execution.
        uow.commitWork();
        return newAccounts;
    }
}
