    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: 'true' },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: 'true' }
  ];

  handleSave(event) {
    const draftValues = event.detail.draftValues;
    const promises = draftValues.map(draft => updateRecord({ fields: { ...draft } }));

    Promise.all(promises)
      .then(() => {
        this.dispatchEvent(
          new ShowToastEvent({
            title: 'Contacts updated',
            variant: 'success'
          })
        );
        this.draftValues = [];
        refreshApex(this.wiredContacts);
      })
      .catch(error => {
        const message = error.body?.message || 'Could not save contacts';
        this.dispatchEvent(
          new ShowToastEvent({
            title: 'Could not save contacts',
            variant: 'error',
            message: message
          })
        );
