        // load immediately on component insertion
        this.loadStats();
        // listen for visibility change on the document
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        clearInterval(this._intervalId);
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    loadStats() {
        // never start a request while the previous one is still in flight
        if (this.pendingRequest) return;
        // while the page is hidden, make no requests
        if (document.hidden) return;

        this.pendingRequest = true;
        // reset state before the new request
        this.errorMessage = null;
        this.hasError = false;
        this.hasData = false;

        getQueueStats()
            .then(result => {
                this.pendingRequest = false;
                this.waiting = result.waiting;
                this.longestWaitMinutes = result.longestWaitMinutes;
                this.hasData = true;
            })
            .catch(error => {
                this.pendingRequest = false;
                this.hasError = true;
                this.errorMessage = error.body.message;
            });
    }

    handleVisibilityChange() {
        // when the page becomes visible again, load immediately
        // the existing interval will continue the 60‑second refresh cycle
        this.loadStats();
    }
}
