public class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Query 1: Retrieve current primary affiliations for the contacts in the map
        Map<Id, npe5__Affiliation__c> contactToCurrentPrimaryAffiliation = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c, npe5__Primary__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
            AND npe5__Status__c = 'Current'
        ]) {
            if (aff.npe5__Primary__c) {
                contactToCurrentPrimaryAffiliation.put(aff.npe5__Contact__c, aff);
            }
        }

        // Query 2: Retrieve each contact's primary affiliation lookup field
        Map<Id, Contact> contactToPrimaryAffiliationLookup = new Map<Id, Contact>();
        for (Contact con : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            contactToPrimaryAffiliationLookup.put(con.Id, con);
        }

        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<Contact> contactsToUpdate = new List<Contact>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);

            // If the organization is already the contact's current primary affiliation, do nothing
            npe5__Affiliation__c currentPrimary = contactToCurrentPrimaryAffiliation.get(contactId);
            if (currentPrimary != null && currentPrimary.npe5__Organization__c == orgId) {
                continue;
            }

            // If a current primary affiliation exists, end it
            if (currentPrimary != null) {
                currentPrimary.npe5__Status__c = 'Former';
                currentPrimary.npe5__Primary__c = false;
                currentPrimary.npe5__EndDate__c = Date.today();
                affiliationsToUpdate.add(currentPrimary);
            }

            // Create a new primary affiliation for the new employer organization
            npe5__Affiliation__c newAffiliation = new npe5__Affiliation__c();
            newAffiliation.npe5__Contact__c = contactId;
            newAffiliation.npe5__Organization__c = orgId;
            newAffiliation.npe5__Status__c = 'Current';
            newAffiliation.npe5__Primary__c = true;
            newAffiliation.npe5__StartDate__c = Date.today();
            affiliationsToUpdate.add(newAffiliation);

            // Update the contact's primary affiliation lookup to point to the new organization
            Contact con = contactToPrimaryAffiliationLookup.get(contactId);
            if (con != null) {
                con.npsp__Primary_Affiliation__c = orgId;
                contactsToUpdate.add(con);
            }
        }

        if (!affiliationsToUpdate.isEmpty()) {
            Database.update(affiliationsToUpdate);
        }
        if (!contactsToUpdate.isEmpty()) {
            Database.update(contactsToUpdate);
        }
    }
}
