public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {

        // 1. Validate that the contact exists
        Contact con = [SELECT Id, FirstName, LastName, AccountId FROM Contact WHERE Id = :contactId LIMIT 1];
        if (con == null) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }

        // 2. Validate the amount is positive
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be positive: ' + amount);
        }

        // 3. In NPSP Household Account model, the contact's account is the household account
        Id householdAccountId = con.AccountId;

        // 4. Gather all contact IDs in the household (primary + all other members on the same account)
        Set<Id> householdContactIds = new Set<Id>();
        householdContactIds.add(contactId);
        for (Contact hCon : [SELECT Id FROM Contact WHERE AccountId = :householdAccountId AND Id != :contactId]) {
            householdContactIds.add(hCon.Id);
        }

        // 5. Create the Opportunity named "<FirstName> <LastName> Donation yyyy-MM-dd"
        String datePart = String.valueOf(giftDate);  // e.g. "2026-03-01"
        String oppName = con.FirstName + ' ' + con.LastName + ' Donation ' + datePart;

        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = householdAccountId,
            StageName = 'Closed Won',
            CloseDate = giftDate,
            npsp__Primary_Contact__c = contactId
        );
        insert opp;

        // 6. Assign contact roles: primary contact gets 'Donor', others get 'Household Member'
        // First, check for any existing roles on this opportunity for these contacts
        Map<Id, String> contactExistingRole = new Map<Id, String>();
        for (OpportunityContactRoleocr : [SELECT ContactId, Role FROM OpportunityContactRole WHERE OpportunityId = :opp.Id AND ContactId IN :householdContactIds]) {
            contactExistingRole.put(ocr.ContactId, ocr.Role);
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        for (Id cId : householdContactIds) {
            String roleName = (cId == contactId) ? 'Donor' : 'Household Member';
            // Only insert if the contact does not already have a role on this opportunity
            if (!contactExistingRole.containsKey(cId)) {
                rolesToInsert.add(new OpportunityContactRole(
                    OpportunityId = opp.Id,
                    ContactId = cId,
                    Role = roleName
                ));
            }
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }

        // 7. Insert the payment: paid, full amount, payment date = giftDate
        // Check to avoid duplicate payments
        if [SELECT Id FROM npe01__OppPayment__c WHERE npe01__Opportunity__c = :opp.Id LIMIT 1].isEmpty() {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opp.Id,
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Paid__c = true,
                npe01__Scheduled_Date__c = giftDate
            );
            insert payment;
        }

        return opp.Id;
    }
}
