public with sharing class DiscountApprovalService {
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }
        if (discountPercent <= 15) {
            return true;
        }
        // Check if the running user has the Approve_Large_Discount custom permission
        Set<Id> permIds = UserInfo.getPermissionIds();
        for (CustomPermission cp : [SELECT Id FROM CustomPermission WHERE Name = 'Approve_Large_Discount']) {
            if (permIds.contains(cp.Id)) {
                return true;
            }
        }
        return false;
    }
