public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // If the running user cannot read FB_Employee__c at all, return an empty list
        if (!Schema.SObjectType.FB_Employee__c.getDescribe().isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Collect field API names the running user can read
        List<String> selectedFields = new List<String>{'Id', 'Name'};

        for (String fieldApiName : new List<String>{'Department__c', 'Salary__c', 'Personal_Email__c'}) {
            Schema.DescribeFieldResult fieldDescribe = 
                Schema.SObjectType.FB_Employee__c.fields.getMap().get(fieldApiName).getDescribe();
            if (fieldDescribe.isAccessible()) {
                selectedFields.add(fieldApiName);
            }
        }

        // Build and execute the SOQL query
        String query = 'SELECT ' + String.join(selectedFields, ',') + 
                       ' FROM FB_Employee__c ORDER BY Name ASC';

        return (List<FB_Employee__c>) Database.query(query);
    }
}
