```apex
public with sharing class TA_Opportunity_CollectForErpSync 
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    /// <summary>
    /// Static set accumulating Opportunity IDs that need ERP sync across trigger chunks.
    /// Cleared by the DML finalizer after enqueuing the job.
    /// </summary>
    public static Set<Id> idsToSync = new Set<Id>();

    /// <summary>
    /// AfterInsert handler: collects all new Opportunity IDs for ERP sync.
    /// Called by TAF for each trigger chunk during after insert context.
    /// </summary>
    public void afterInsert(List<SObject> triggerNew) {
        for (Opportunity opp : (List<Opportunity>) triggerNew) {
            idsToSync.add(opp.Id);
        }
    }

    /// <summary>
    /// AfterUpdate handler: collects Opportunity IDs where StageName changed.
    /// Called by TAF for each trigger chunk during after update context.
    /// </summary>
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Build a map of old Opportunity records keyed by ID
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>();
        for (SObject s : triggerOld) {
            oldMap.put(s.Id, (Opportunity) s);
        }

        // For each new Opportunity, check if StageName differs from old value
        for (Opportunity opp : (List<Opportunity>) triggerNew) {
            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp != null && opp.StageName != oldOpp.StageName) {
                idsToSync.add(opp.Id);
            }
        }
    }
}
