public class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    /// <summary>
    /// DML finalizer execute method called by TAF at the end of every DML operation
    /// it handles. Enqueues a single OpportunityErpSyncJob with all collected Ids,
    /// or enqueues no job when none of the synced Opportunities require it.
    /// </summary>
    public void execute(FinalizerHandler.Context context) {
        if (!TA_Opportunity_CollectForErpSync.idsToSync.isEmpty()) {
            OpportunityErpSyncJob job = new OpportunityErpSyncJob(
                new Set<Id>(TA_Opportunity_CollectForErpSync.idsToSync)
            );
            Messaging.enqueueJob(job);
            // Clear the static set so the next DML operation starts fresh.
            TA_Opportunity_CollectForErpSync.idsToSync.clear();
        }
        // If idsToSync is empty, no job is enqueued — satisfies the "no job at all when none does" rule.
    }
}
