public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static Set<Id> opportunitiesWithTask = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasks = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity oppNew = triggerNew[i];
            Opportunity oppOld = triggerOld[i];

            // Skip if we've already created a task for this opportunity in this transaction.
            // This handles the case where the rounding action (Order 20) re-runs the afterUpdate context,
            // ensuring at most one "Amount changed" task per opportunity per transaction.
            if (opportunitiesWithTask.contains(oppNew.Id)) {
                continue;
            }

            // Check if Amount actually changed from old to new (user's change, not the rounding action's update).
            // Inserts are out of scope; this only runs on updates.
            if (oppOld.Amount != oppNew.Amount) {
                Task t = new Task(
                    Subject = 'Amount changed',
                    WhatId = oppNew.Id,
                    Status = 'Completed'
                );
                tasks.add(t);
                opportunitiesWithTask.add(oppNew.Id);
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }
}
